import matplotlib.pyplot as plt
from itertools import zip_longest
# Constants
COLORS = ['red', 'green', 'blue', 'yellow', 'purple']
def task_func(data, labels):
    colors = COLORS * (len(labels) // len(COLORS) + 1)
    fig, ax = plt.subplots()
    for series, label, color in zip_longest(data, labels, colors):
        if series is not None:
            ax.plot(series, label=label, color=color if color is not None else 'black')
    if ax.get_legend_handles_labels()[0]:
        ax.legend()
    return ax

