import re
import os
import shutil
from datetime import datetime

def task_func(directory):
    """Move immediate files into folders named for their first unbracketed text."""
    moved = {}
    for filename in os.listdir(directory):
        source = os.path.join(directory, filename)
        if not os.path.isfile(source):
            continue

        # Track brackets so text inside bracketed sections is not a candidate.
        depth = 0
        folder = None
        for match in re.finditer(r'\[|\]|[^\[\]]+', filename):
            text = match.group()
            if text == '[':
                depth += 1
            elif text == ']':
                depth = max(0, depth - 1)
            elif depth == 0 and text.strip():
                folder = text.strip()
                break

        if folder is None:
            continue
        destination = os.path.join(directory, folder)
        os.makedirs(destination, exist_ok=True)
        shutil.move(source, os.path.join(destination, filename))
        moved.setdefault(folder, []).append(filename)

    return os.fsdecode(directory), moved

