import random
import string
POSSIBLE_LETTERS = ['a', 'b', 'c']
def task_func(word):
    if any(not char.isalpha() for char in word):
        raise ValueError('Input must contain only letters')
    if len(word) < 2:
        return [''] * len(POSSIBLE_LETTERS)
    pairs = [word[i:i + 2] for i in range(len(word) - 1)]
    return [random.choice(pairs) for _ in POSSIBLE_LETTERS]

